// Circuits in the real window (ADR 0005): the application starts on the 7-segment circuit given by --circuit with
// firmware/src/counter.c, then circuits are selected and loaded from the page. The components are drawn by the
// rendering module of their type from the state computed by the electrical model in C++; the page decides nothing.
// window.sfFixtures is generated by tests/CMakeLists.txt from circuits/led-buttons.json and circuits/arduino-demo.json.
jasmine.getEnv().configure({random: false});

describe("Circuits", () => {
  const sf = () => window.siliconForge;
  const fixtures = window.sfFixtures;
  const element = (id) => document.getElementById(id);
  const display = () => document.querySelector(".bb-seven-segment");
  const rejection = async (promise) => {
    try { await promise; } catch (error) { return error; }
    throw new Error("the call did not reject");
  };
  const until = async (predicate, what, timeoutMs = 5000) => {
    const deadline = performance.now() + timeoutMs;
    while (!predicate()) {
      if (performance.now() > deadline) throw new Error(`timeout waiting for ${what}`);
      await new Promise((resolve) => setTimeout(resolve, 20));
    }
  };
  /** Two frames after a pause: the second one covers no simulated time, so it carries present values, not averages. */
  const freeze = async () => {
    await sf().pause();
    const paused = (await sf().waitFor((state) => !state.running, 2000)).frame;
    await sf().waitFor((state) => state.frame >= paused + 2, 2000);
  };
  const choose = (id, name, content) => {
    const transfer = new DataTransfer();
    transfer.items.add(new File([content], name, {type: "application/json"}));
    element(id).files = transfer.files;
    element(id).dispatchEvent(new Event("change", {bubbles: true}));
  };

  beforeAll(async () => {
    await webFront.ready;
    await sf().waitFor((state) => state.mcu === "ATmega328P" && state.firmware === "counter.hex", 5000);
    await until(() => display() !== null, "the display of the circuit given on the command line");
  });

  it("starts on the circuit of the command line and names the pins of its components", async () => {
    const circuit = await sf().circuit();
    expect(circuit.id).toBe("seven-segment");
    expect(circuit.name).toBe("7-segment counter");
    expect(element("circuit-select").value).toBe("seven-segment");
    expect(circuit.components.find((component) => component.id === "r-a").pin).toBe("D2");
    expect(circuit.components.find((component) => component.id === "display").properties.forwardVoltage).toBe(2);
    expect(await sf().circuits()).toEqual(jasmine.arrayContaining(["arduino-demo", "led-buttons", "seven-segment"]));
    expect(document.querySelectorAll("#breadboard .bb-resistor").length).toBe(8);
  });

  it("shows on the 7-segment display each digit the firmware counts", async () => {
    await sf().reset();
    await sf().setSpeed(2);
    await sf().run();
    for (const digit of ["0", "1", "2", "3", "4"]) {
      // The firmware lights the digit, then sends it: once it is in the serial monitor it stays displayed for 0.5 s.
      await sf().waitForSerial(`${digit}\r\n`, 5000);
      await freeze();
      expect(display().dataset.digit).toBe(digit);
      expect(display().dataset.point).toBe(String(Number(digit) % 2 === 1));
      expect(sf().component("display")["a.brightness"]).toBe(digit === "1" || digit === "4" ? 0 : 1);
      await sf().run();
    }
    await sf().pause();
  });

  it("decodes the serial frames of D1 in the logic analyser", async () => {
    await sf().instruments.sync();
    const decoded = sf().instruments.decodeUart("D1");
    expect(decoded.baud).toBe(9600);  // Found from the shortest pulse
    expect(decoded.text.startsWith("0\r\n1\r\n2\r\n")).toBe(true);
    expect(decoded.bytes.every((byte) => byte.ok)).toBe(true);
    expect(decoded.bytes[1].t - decoded.bytes[0].t).toBeCloseTo(10 / 9615.4, 6);  // UBRR0 = 103: 16 MHz / 16 / 104
    expect(sf().output.startsWith(decoded.text.slice(0, 9))).toBe(true);
  });

  it("refuses an interaction the component does not have, with a typed error", async () => {
    const unknown = await rejection(sf().setComponent("no-such-part", "pressed", 1));
    expect(unknown.code).toBe("siliconforge.unknownComponent");
    const readOnly = await rejection(sf().setComponent("display", "a.brightness", 1));
    expect(readOnly.code).toBe("siliconforge.invalidValue");
    expect(readOnly.message).toContain("read-only");
  });

  it("loads an example: another circuit, its firmware, and buttons that light the LED", async () => {
    await sf().loadExample("buttons");
    await sf().waitFor((state) => state.firmware === "buttons.hex" && state.running, 5000);
    await until(() => document.querySelector('.bb-led[data-pin="D9"]') !== null, "the LED of the new circuit");
    expect(display()).toBeNull();
    expect(element("circuit-select").value).toBe("led-buttons");
    expect(element("circuit-name").textContent).toBe("LED and two buttons");
    const led = () => Number(document.querySelector('.bb-led[data-pin="D9"]').dataset.level);
    await sf().waitForPin("D2", sf().pinState.high, 3000);  // The firmware enabled the pull-up
    expect(led()).toBe(0);

    const hold = document.querySelector('.bb-button[data-pin="D2"]');
    hold.dispatchEvent(new PointerEvent("pointerdown", {bubbles: true}));
    await sf().waitFor(() => led() === 1, 3000);
    expect(sf().pin("D2").state).toBe(sf().pinState.low);
    expect(sf().component("button-d2").pressed).toBe(true);
    hold.dispatchEvent(new PointerEvent("pointerup", {bubbles: true}));
    await sf().waitFor(() => led() === 0, 3000);

    const latch = document.querySelector('.bb-button[data-pin="D3"]');
    latch.dispatchEvent(new PointerEvent("pointerdown", {bubbles: true}));
    await sf().waitFor(() => led() === 1, 3000);
    latch.dispatchEvent(new PointerEvent("pointerup", {bubbles: true}));
    await new Promise((resolve) => setTimeout(resolve, 200));
    expect(led()).toBe(1);  // Latched by the firmware
  });

  it("loads a circuit chosen with the file input, keeping the firmware of the same MCU", async () => {
    choose("circuit-file", "mine.json", JSON.stringify({...fixtures.circuit, name: "My own circuit"}));
    await until(() => element("circuit-name").textContent === "My own circuit", "the loaded circuit");
    expect(element("circuit-error").hidden).toBe(true);
    expect(element("circuit-select").selectedOptions[0].textContent).toBe("My own circuit (loaded)");
    expect(sf().state.firmware).toBe("buttons.hex");
    expect((await sf().circuit()).id).toBe("mine.json");
  });

  it("reports an invalid circuit with its JSON path and keeps the current one", async () => {
    const broken = structuredClone(fixtures.circuit);
    broken.components[1].properties.resistance = -5;
    choose("circuit-file", "broken.json", JSON.stringify(broken));
    await until(() => !element("circuit-error").hidden, "the circuit error");
    expect(element("circuit-error").textContent).toContain("Cannot load broken.json");
    expect(element("circuit-error").textContent).toContain("/components/1/properties/resistance");
    expect(element("circuit-name").textContent).toBe("My own circuit");

    const invalid = await rejection(sf().loadCircuit("broken.json", JSON.stringify(broken)));
    expect(invalid.code).toBe("siliconforge.invalidCircuit");
    expect(invalid.message.startsWith("/components/1/properties/resistance: ")).toBe(true);
    const tooFar = await rejection(sf().loadCircuit("far.json", JSON.stringify({...fixtures.circuit, chip: {mcu: "atmega328p", column: 25}, components: [], wires: []})));
    expect(tooFar.code).toBe("siliconforge.invalidCircuit");
    expect(tooFar.message.startsWith("/chip/column: ")).toBe(true);
    const unknown = await rejection(sf().selectCircuit("no-such-circuit"));
    expect(unknown.code).toBe("siliconforge.unknownCircuit");
    expect((await sf().circuit()).id).toBe("mine.json");
  });

  it("signals a short circuit between an output and a rail", async () => {
    await sf().loadExample("blink");
    expect(element("shorts").hidden).toBe(true);
    const shorted = structuredClone(fixtures.demo);
    shorted.wires.push({from: "g15", to: "T-15", color: "white"});  // D13 straight to ground
    await sf().loadCircuit("shorted.json", JSON.stringify(shorted));
    await sf().waitFor((state) => state.shorts.length === 1, 5000);  // As soon as the firmware drives D13 high
    await until(() => !element("shorts").hidden, "the short-circuit banner");
    expect(element("shorts").textContent).toContain("D13");
    expect(element("shorts").textContent).toContain("ground rail");
    await sf().selectCircuit("arduino-demo");
    await sf().waitFor((state) => state.shorts.length === 0, 5000);
    await until(() => element("shorts").hidden, "the banner to clear");
  });

  it("leaves a bare board to a microcontroller the circuit was not made for", async () => {
    await sf().loadMcu(JSON.stringify({...fixtures.mcu, name: "Another chip"}));
    await sf().waitFor((state) => state.mcu === "Another chip", 5000);
    await until(() => document.querySelector("#breadboard .bb-chip-name")?.textContent === "another chip", "the bare board");
    expect(await sf().circuit()).toBeNull();
    expect(document.querySelectorAll("#breadboard .bb-led, #breadboard .bb-wire").length).toBe(0);
    expect(document.querySelectorAll("#breadboard .bb-leg.bb-io").length).toBeGreaterThan(20);
    await sf().selectMcu("atmega328p");
    await until(() => document.querySelector('#breadboard .bb-led[data-pin="D13"]') !== null, "the circuit to come back with its MCU");
  });
});
